/*
 * DigiShack service worker.
 *
 * Hand-written, not generated by a plugin. next-pwa and friends want to precache the
 * whole build manifest, and this app is the wrong shape for that: most of what matters
 * on screen is live radio state arriving over a WebSocket and a poll, and a worker that
 * serves it from a cache is a worker that shows an operator a decode list from twenty
 * minutes ago. Precaching HTML would be actively harmful here.
 *
 * So the rules are narrow and the default is "get out of the way":
 *
 *   /api/*, /ws, anything not GET   -> NEVER touched. Straight to the network.
 *   /_next/static/*, /icons/*       -> cache-first. Content-hashed or effectively static.
 *   navigations (HTML)              -> network-first, cache as a fallback, then offline.
 *   everything else                 -> network, with a cached copy as a fallback.
 *
 * The cache name carries the app version, which arrives as a query string on the
 * registration URL (`/sw.js?v=1.118.0`). A changed URL is a new worker as far as the
 * browser is concerned, so a release installs a fresh worker and the activate handler
 * deletes every cache that is not the current version. That is the whole invalidation
 * story: no manifest to keep in step, and no constant in here to remember to bump.
 */

const VERSION = new URL(self.location.href).searchParams.get("v") || "dev";
const CACHE = `digishack-${VERSION}`;
const OFFLINE_URL = "/offline.html";

// Small and fixed. Everything else earns its place in the cache by being requested.
const PRECACHE = [OFFLINE_URL, "/icons/icon-192.png", "/manifest.webmanifest"];

self.addEventListener("install", (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(CACHE);
      // Individually, not addAll: addAll is atomic, so one 404 throws away the whole
      // install and the worker never activates.
      await Promise.all(
        PRECACHE.map(async (url) => {
          try {
            await cache.add(new Request(url, { cache: "reload" }));
          } catch {
            // A missing precache entry is not worth failing an install over.
          }
        }),
      );
    })(),
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      // Older versions of this app, and nothing else — a shared origin could have
      // other workers' caches on it.
      const names = await caches.keys();
      await Promise.all(
        names
          .filter((n) => n.startsWith("digishack-") && n !== CACHE)
          .map((n) => caches.delete(n)),
      );
      // Take over open tabs now rather than on their next navigation, so a page that
      // was loaded before the update stops being served by the previous worker.
      await self.clients.claim();
    })(),
  );
});

// The page asks for this after it has told the operator an update is waiting.
self.addEventListener("message", (event) => {
  if (event.data === "skip-waiting") void self.skipWaiting();
});

/** True for anything that must never be served from a cache. */
function isLive(url, request) {
  if (request.method !== "GET") return true;
  if (url.origin !== self.location.origin) return true;
  // The bridge status poll, every mutation, the WebSocket upgrade, and the streaming
  // audio/spectrum endpoints. Caching any of these produces a stale radio.
  if (url.pathname.startsWith("/api/")) return true;
  if (url.pathname.startsWith("/ws")) return true;
  // Server-sent events and range requests: a cached partial response is worse than
  // no response.
  if (request.headers.get("accept") === "text/event-stream") return true;
  if (request.headers.has("range")) return true;
  return false;
}

/** Content-hashed by the build, or an icon that changes at most once a release. */
function isImmutable(url) {
  return (
    url.pathname.startsWith("/_next/static/") ||
    url.pathname.startsWith("/icons/") ||
    url.pathname === "/manifest.webmanifest"
  );
}

self.addEventListener("fetch", (event) => {
  const { request } = event;
  const url = new URL(request.url);

  if (isLive(url, request)) return; // no respondWith — the browser handles it

  if (isImmutable(url)) {
    event.respondWith(
      (async () => {
        const cached = await caches.match(request);
        if (cached) return cached;
        const res = await fetch(request);
        if (res.ok) {
          const cache = await caches.open(CACHE);
          void cache.put(request, res.clone());
        }
        return res;
      })(),
    );
    return;
  }

  if (request.mode === "navigate") {
    event.respondWith(
      (async () => {
        try {
          // Network first, always. A logged-in shack page must be the live one when
          // the network is there; the cache exists for when it is not.
          const res = await fetch(request);
          if (res.ok) {
            const cache = await caches.open(CACHE);
            void cache.put(request, res.clone());
          }
          return res;
        } catch {
          const cached = await caches.match(request);
          if (cached) return cached;
          const offline = await caches.match(OFFLINE_URL);
          if (offline) return offline;
          return new Response("Offline", {
            status: 503,
            headers: { "content-type": "text/plain" },
          });
        }
      })(),
    );
    return;
  }

  // Fonts, the audio worklet, anything else same-origin and static-ish.
  event.respondWith(
    (async () => {
      try {
        const res = await fetch(request);
        if (res.ok) {
          const cache = await caches.open(CACHE);
          void cache.put(request, res.clone());
        }
        return res;
      } catch {
        const cached = await caches.match(request);
        if (cached) return cached;
        throw new Error("offline and uncached");
      }
    })(),
  );
});
